const form=document.querySelector('#admin-form'),fields=document.querySelector('#admin-fields'),status=document.querySelector('#admin-status'),saveStatus=document.querySelector('#admin-save-status'),services=document.querySelector('#admin-services'),saveButton=document.querySelector('#save-settings');
let revision=0,dirty=false,canEditManager=false;
const names=['bio','email','phone','whatsapp','contactUrl','bookingUrl','format','availability','managerEmail'];
function serviceCard(service={name:'',price:null,duration:'',description:'',published:false}){
  const card=document.createElement('fieldset');card.className='admin-service';
  card.innerHTML='<legend>Prestation</legend><label>Nom<input data-field="name" required maxlength="100"></label><div class="admin-grid"><label>Tarif en euros <span>(laisser vide si à confirmer)</span><input data-field="price" type="number" min="0" max="10000" step="0.01"></label><label>Durée<input data-field="duration" maxlength="80" placeholder="Par exemple : 45 minutes"></label></div><label>Description<textarea data-field="description" rows="3" maxlength="1200"></textarea></label><label class="checkbox-label"><input data-field="published" type="checkbox"> Afficher cette prestation sur le site</label><button class="remove-service" type="button">Retirer cette prestation</button>';
  for(const input of card.querySelectorAll('[data-field]')){const value=service[input.dataset.field];if(input.type==='checkbox')input.checked=Boolean(value);else input.value=value??'';}
  card.querySelector('.remove-service').addEventListener('click',()=>{if(card.querySelector('[data-field=name]').value&& !confirm('Retirer cette prestation de la liste ? La suppression sera appliquée au prochain enregistrement.'))return;card.remove();dirty=true;});services.append(card);
}
async function api(method='GET',body){const response=await fetch('/api/admin/settings',{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json();}catch{throw new Error('La gestion est indisponible sur cette adresse. Ouvrez le site hébergé Morgane medium.');}if(!response.ok)throw new Error(data.error||'Impossible de charger les informations.');return data;}
(async()=>{try{const data=await api();revision=data.revision;for(const name of names)form.elements[name].value=data.settings[name]||'';data.settings.services.forEach(serviceCard);canEditManager=data.actor.isOwner;document.querySelector('#manager-access').hidden=!canEditManager;form.elements.managerEmail.readOnly=!canEditManager;document.querySelector('#admin-account').textContent='Connecté : '+data.actor.email;fields.disabled=false;status.textContent=data.updatedAt?'Dernier enregistrement : '+new Date(data.updatedAt).toLocaleString('fr-FR'):'Vous pouvez renseigner vos premières informations.';}catch(error){status.textContent=error.message;}})();
form.addEventListener('input',()=>{dirty=true;saveStatus.textContent='Modifications en attente d’enregistrement.';});
document.querySelector('#add-service').addEventListener('click',()=>{if(services.children.length>=30){saveStatus.textContent='Vous pouvez gérer jusqu’à 30 prestations.';return;}serviceCard();dirty=true;});
form.addEventListener('submit',async event=>{event.preventDefault();if(!form.reportValidity())return;const settings=Object.fromEntries(names.map(name=>[name,form.elements[name].value]));settings.services=[...services.children].map(card=>({name:card.querySelector('[data-field=name]').value,price:card.querySelector('[data-field=price]').value===''?null:Number(card.querySelector('[data-field=price]').value),duration:card.querySelector('[data-field=duration]').value,description:card.querySelector('[data-field=description]').value,published:card.querySelector('[data-field=published]').checked}));saveButton.disabled=true;saveStatus.textContent='Enregistrement en cours…';try{const data=await api('PUT',{settings,revision});revision=data.revision;dirty=false;saveStatus.textContent='Informations enregistrées et publiées sur le site.';status.textContent='Dernier enregistrement : '+new Date(data.updatedAt).toLocaleString('fr-FR');}catch(error){saveStatus.textContent=error.message+' Votre saisie reste affichée.';}finally{saveButton.disabled=false;}});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
